      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "The femtosecond solid-state laser made extremely short, stable pulses broadly accessible and transformed ultrafast science. Its lasting impact as both a tool and a platform is exceptional.",
        "attribution": "Moulton's titanium-sapphire laser and the distinct passive mode-locking advances of Keller and Sibbett provide a coherent, technically grounded attribution.",
        "maturity": "Decades of reliable use across laboratories and fields establish the result well beyond its initial demonstrations.",
        "uncertainties": [
          "The relative weighting of the Kerr-lens and semiconductor saturable-absorber routes needs careful assessment because both were important and developed in a competitive period."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have pushed precision timekeeping to a level that enables new tests of fundamental physics and sensitive measurements of gravitational potential. This is a major advance in measurement.",
        "attribution": "Katori's lattice-clock concept and development and Ye's central experimental advances are distinct, complementary contributions.",
        "maturity": "Independent clock systems and sustained improvements in accuracy and stability support a mature achievement with continuing scientific use.",
        "uncertainties": [
          "The prize boundary between the original clock concept and subsequent precision demonstrations would need a clear account."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light turns quantum noise from a fundamental limit into an experimentally manageable resource. Its use in gravitational-wave interferometry demonstrates a striking connection between quantum optics and precision measurement.",
        "attribution": "Caves established the key theoretical framework; Kimble helped develop the experimental field, and Mavalvala was central to its realization in interferometry.",
        "maturity": "The technique has moved from proposal and laboratory demonstration to operational use in gravitational-wave observatories.",
        "uncertainties": [
          "Several researchers made essential advances in squeezed-light generation and interferometric integration; selecting a compact laureate group requires a detailed contribution history."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry uses matter-wave coherence for precise measurements of acceleration, rotation, and fundamental properties. It has opened a powerful measurement approach with both basic-physics and practical reach.",
        "attribution": "Bordé's early atom-interferometry work, Pritchard's foundational experiments, and Kasevich's influential precision demonstrations represent complementary stages of the field.",
        "maturity": "The method has been repeatedly demonstrated and diversified, though its ultimate reach in field instruments and fundamental tests is still developing.",
        "uncertainties": [
          "The candidate combines a broad sequence of developments, so the essential discovery and appropriate attribution need sharper definition."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Alexandre Blais",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a controllable, measurable interaction between microwave photons and artificial atoms. It is a foundational advance for quantum optics in solid-state systems and quantum information.",
        "attribution": "Blais developed the key theoretical description, while Schoelkopf and Girvin were central to establishing the experimental and conceptual framework.",
        "maturity": "Strong coupling and coherent control are well established, with extensive replication and continuing development into larger quantum devices.",
        "uncertainties": [
          "The rapid expansion of the field makes it important to distinguish the original strong-coupling achievement from later circuit and processor advances."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography brought quantum measurement and entanglement into a practical information-security task and helped define quantum communication as a field.",
        "attribution": "Ekert's entanglement-based protocol and Bennett and Brassard's foundational protocol and experimental work are distinct, well-known contributions.",
        "maturity": "The principles and protocols are mature and have been demonstrated in increasingly capable systems, although broad secure deployment remains an engineering challenge.",
        "uncertainties": [
          "The candidate spans different approaches to quantum key distribution, and their relative priority and influence should be assessed carefully.",
          "There are two credited-name variants for Ekert; the proposed name follows the shorter form in the list."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Harald Rose",
        "Maximilian Haider",
        "Ondrej L. Krivanek"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction removed a major practical limit in electron microscopy, enabling atomic-scale imaging and analysis that changed how materials can be studied.",
        "attribution": "Rose's theoretical and design contributions, Haider's realization of correctors, and Krivanek's advances in scanning transmission microscopy and spectroscopy form a strong attribution case.",
        "maturity": "Corrected instruments are established in research laboratories and have produced sustained scientific results over many years.",
        "uncertainties": [
          "The long development involved additional teams and institutions, so the credit boundary between invention, implementation, and later instrument advances merits scrutiny."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B054",
      "proposed_laureates": [
        "Gerhard Rempe",
        "H. Jeff Kimble",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum interfaces between light and matter are essential for quantum memories and networks. The work established ways to transfer and preserve quantum states across different physical systems.",
        "attribution": "Rempe, Kimble, and Lukin made influential, complementary contributions to atom-photon interfaces, cavity quantum electrodynamics, and quantum-network concepts and demonstrations.",
        "maturity": "Core interface experiments are well established, but scalable networks and robust long-distance operation remain active research goals.",
        "uncertainties": [
          "The discovery is broad and encompasses several platforms and milestones; a specific, prize-worthy central achievement and its attribution need to be delimited."
        ]
      }
    }
  ]
